namespace sv_9699a55614af4850a9aaff904778e5b7.Services;

public class WarehouseStateService
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public List<Warehouse> Warehouses { get; } =
    [
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
        new("WH-004", "Warehouse D - Industrial Park")
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record Warehouse(string Id, string Name);

namespace sv_9699a55614af4850a9aaff904778e5b7.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;
    private int _currentLowStockCount;

    public int CurrentLowStockCount => _currentLowStockCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should refresh.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning a random low-stock count for the warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants polling to be active. Polling runs while at least one subscriber exists.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling (e.g., disposed/navigated away).
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _timer?.Dispose();
            _timer = null;
        }
    }

    private async void PollCallback(object? state)
    {
        await RefreshAlertDataAsync();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately refresh when warehouse changes
        await RefreshAlertDataAsync();
    }

    private async Task RefreshAlertDataAsync()
    {
        _currentLowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        await NotifySubscribers();
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _timer?.Dispose();
    }
}

