{"file_text": "@page "/dashboard"
@rendermode InteractiveServer
@using sv_9699a55614af4850a9aaff904778e5b7.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <h5 class="mb-0">📍 @WarehouseState.SelectedWarehouseName</h5>
    </div>
    <div class="card-body">
        <p><strong>Warehouse ID:</strong> @WarehouseState.SelectedWarehouseId</p>
        <p>
            <strong>Low Stock Alerts:</strong>
            @if (AlertService.CurrentLowStockCount > 0)
            {
                <span class="badge bg-danger fs-6">@AlertService.CurrentLowStockCount items below minimum</span>
            }
            else
            {
                <span class="badge bg-success fs-6">All stock levels OK</span>
            }
        </p>
        <p class="text-muted"><small>Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small></p>
    </div>
</div>

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">📋 Activity Log</h5>
    </div>
    <div class="card-body">
        <ul class="list-group list-group-flush">
            @foreach (var entry in _log.TakeLast(10).Reverse())
            {
                <li class="list-group-item">@entry</li>
            }
        </ul>
    </div>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;
    private readonly List<string> _log = new();

    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;

        // Start polling when dashboard becomes visible
        AlertService.StartPolling();
    }

    private Task HandleAlertDataChanged()
    {
        _lastUpdate = DateTime.Now;
        _log.Add($"[{_lastUpdate:HH:mm:ss}] Alert check: {AlertService.CurrentLowStockCount} low-stock items at {WarehouseState.SelectedWarehouseName}");
        return InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Switched to {WarehouseState.SelectedWarehouseName}");
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}
", "path": "/tmp/sv-9699a55614af4850a9aaff904778e5b7/Components/Pages/Dashboard.razor"}

